import datetime
import unittest
from src.dateparse.parser import parse_date

class DateBehavior(unittest.TestCase):
    def test_tab_and_newline_padding(self):
        self.assertEqual(parse_date('\t2024-02-29\n'), datetime.date(2024, 2, 29))

    def test_invalid_date_stays_invalid(self):
        with self.assertRaises(ValueError):
            parse_date('2024-02-30')

    def test_unpadded_date(self):
        self.assertEqual(parse_date('2025-12-31'), datetime.date(2025, 12, 31))
